16	interface AuthenticityData {
17	  authenticity_score: number;
18	  risk_level: "low" | "medium" | "high";
19	  flags: string[];
20	  summary: string;
21	}
22	
23	interface CandidateRowProps {
24	  result: Result;
25	  index: number;
26	  isSelected: boolean;
27	  isActive: boolean;
28	  jobId?: string | null;
29	  jobTitle?: string | null;
30	  onSelect: (id: string) => void;
31	  onToggleSelect: (resumeId: string) => void;
32	  onDownload: (filePath: string, filename: string) => void;
33	  onDismiss: (resumeId: string) => void;
34	  formatCandidateName: (filename: string) => string;
35	  currentStage?: HiringStage | null;
36	  isDuplicate?: boolean;
37	  tags?: CandidateTag[];
38	  assigneeEmail?: string | null;
39	  blindMode?: boolean;
40	  authenticityData?: AuthenticityData | null;
41	}
42	
43	const getScoreColor = (score: number) => {
44	  if (score >= 70) return "bg-score-skills";
45	  if (score >= 40) return "bg-warning";
46	  return "bg-destructive";
47	};
48	
49	const getScoreTextColor = (score: number) => {
50	  if (score >= 70) return "text-score-skills";
51	  if (score >= 40) return "text-warning";
52	  return "text-destructive";
53	};
54	
55	const STAGE_BADGE_CLASSES: Record<string, string> = {
56	  applied: "border-border bg-muted/50 text-muted-foreground",
57	  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
58	  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
59	  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
60	  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
61	  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
62	};
63	
64	const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
65	  if (score >= 70) return { label: "Strong", variant: "success" };
66	  if (score >= 40) return { label: "Good", variant: "warning" };
67	  return { label: "Weak", variant: "destructive" };
68	};
69	
70	const CandidateRow = ({
71	  result: r,
72	  index,
73	  isSelected,
74	  isActive,
75	  jobId,
76	  jobTitle,
77	  onSelect,
78	  onToggleSelect,
79	  onDownload,
80	  onDismiss,
81	  formatCandidateName,
82	  currentStage,
83	  isDuplicate,
84	  tags = [],
85	  assigneeEmail,
86	  blindMode = false,
87	  authenticityData,
88	}: CandidateRowProps) => {
89	  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
90	  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
91	  const linkedinUrl = extractLinkedInUrl(r);
92	
93	  return (
94	    <>
95	      <TableRow
96	        className={`transition-colors animate-in fade-in slide-in-from-bottom-1 duration-200 ${r.pending ? "opacity-50 cursor-default" : "cursor-pointer"} ${isActive ? "bg-primary/5 hover:bg-primary/5" : "hover:bg-muted/50"}`}
97	        style={{ animationDelay: `${Math.min(index * 40, 400)}ms`, animationFillMode: "backwards" }}
98	        onClick={() => !r.pending && onSelect(r.id)}
99	      >
100	        <TableCell onClick={(e) => e.stopPropagation()}>
101	          <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
102	        </TableCell>
103	        <TableCell className="text-center">
104	          {r.pending
105	            ? <span className="text-sm text-muted-foreground">—</span>
106	            : <span className="text-sm font-medium tabular-nums text-muted-foreground">{index + 1}</span>}
107	        </TableCell>
108	        <TableCell className="font-medium">
109	          <div className="flex flex-col gap-0.5">
110	            <div className="flex items-center gap-1.5 flex-wrap">
111	              <span className="text-sm">
112	                {blindMode
113	                  ? `Candidate ${index + 1}`
114	                  : (r.candidate_name || formatCandidateName(r.filename))}
115	              </span>
116	              {isDuplicate && (
117	                <Badge variant="outline" className="text-xs px-1.5 py-0 border-orange-300 text-orange-600 bg-orange-50">
118	                  Duplicate
119	                </Badge>
120	              )}
121	              {!r.pending && currentStage && currentStage !== "applied" && (
122	                <Badge
123	                  variant="outline"
124	                  className={`text-xs px-1.5 py-0 h-4 capitalize border font-medium ${STAGE_BADGE_CLASSES[currentStage] ?? ""}`}
125	                >
126	                  {currentStage}
127	                </Badge>
128	              )}
129	              {authenticityData && !blindMode && (
130	                <AuthenticityBadge data={authenticityData} />
131	              )}
132	            </div>
133	            {r.candidate_location && !blindMode && (
134	              <span className="flex items-center gap-1 text-xs text-muted-foreground">
135	                <MapPin className="h-3 w-3" /> {r.candidate_location}
136	              </span>
137	            )}
138	            {/* Tag chips */}
139	            {tags.length > 0 && (
140	              <div className="flex flex-wrap gap-1 mt-0.5">
141	                {tags.slice(0, 3).map((t) => (
142	                  <span
143	                    key={t.id}
144	                    className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium text-white leading-4"
145	                    style={{ backgroundColor: t.color }}
146	                  >
147	                    {t.tag}
148	                  </span>
149	                ))}
150	                {tags.length > 3 && (
151	                  <span className="text-xs text-muted-foreground">+{tags.length - 3}</span>
152	                )}
153	              </div>
154	            )}
155	            {/* Assignee badge */}
156	            {assigneeEmail && (
157	              <span className="text-xs text-muted-foreground flex items-center gap-0.5 mt-0.5">
158	                <UserCheck className="h-2.5 w-2.5" />
159	                {assigneeEmail}
160	              </span>
161	            )}
162	          </div>
163	        </TableCell>
164	        <TableCell>
165	          {r.pending ? (
166	            <Badge variant="outline" className="text-xs">Pending</Badge>
167	          ) : (
168	            <div className="flex items-center gap-2">
169	              <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
170	                <div
171	                  className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
172	                  style={{ width: `${Math.min(r.overall_score, 100)}%` }}
173	                />
174	              </div>
175	              <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
176	                {r.overall_score?.toFixed(0)}%
177	              </span>
178	            </div>
179	          )}
180	        </TableCell>
181	        <TableCell>
182	          <div className="flex flex-wrap items-center gap-1">
183	            {!r.pending && strength && (
184	              <Badge variant={strength.variant} className="text-xs transition-colors">{strength.label}</Badge>
185	            )}
186	            {!r.pending && r.scoring_version === "heuristic" && (
187	              <span className="inline-flex items-center text-xs px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium">Quick</span>
188	            )}
189	          </div>
190	        </TableCell>
191	        <TableCell>
192	          <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
193	            {!isActive && (
194	            <TooltipProvider delayDuration={300}>
195	              {r.candidate_phone && (
196	                <Tooltip>
197	                  <TooltipTrigger asChild>
198	                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary transition-colors" aria-label="Copy phone number"
199	                      onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
200	                      <Phone className="h-3.5 w-3.5" />
201	                    </Button>
202	                  </TooltipTrigger>
203	                  <TooltipContent>{r.candidate_phone}</TooltipContent>
204	                </Tooltip>
205	              )}
206	              {r.candidate_email && (
207	                <Tooltip>
208	                  <TooltipTrigger asChild>
209	                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary transition-colors" aria-label="Send email"
210	                      onClick={() => setEmailDialogOpen(true)}>
211	                      <Mail className="h-3.5 w-3.5" />
212	                    </Button>
213	                  </TooltipTrigger>
214	                  <TooltipContent>Email</TooltipContent>
215	                </Tooltip>
216	              )}
217	              {linkedinUrl && (
218	                <Tooltip>
219	                  <TooltipTrigger asChild>
220	                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-[#0A66C2] transition-colors"
221	                      onClick={(e) => { e.stopPropagation(); window.open(linkedinUrl, "_blank", "noopener,noreferrer"); }}>
222	                      <Linkedin className="h-3.5 w-3.5" />
223	                    </Button>
224	                  </TooltipTrigger>
225	                  <TooltipContent>LinkedIn Profile</TooltipContent>
226	                </Tooltip>
227	              )}
228	              {r.file_path && (
229	                <Tooltip>
230	                  <TooltipTrigger asChild>
231	                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary transition-colors" aria-label="Download resume"
232	                      onClick={() => onDownload(r.file_path!, r.filename)}>
233	                      <FileText className="h-3.5 w-3.5" />
234	                    </Button>
235	                  </TooltipTrigger>
236	                  <TooltipContent>Download</TooltipContent>
237	                </Tooltip>
238	              )}
239	              <Tooltip>
240	                <TooltipTrigger asChild>
241	                  <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-amber-500 transition-colors" aria-label="Archive candidate"
242	                    onClick={() => onDismiss(r.resume_id)}>
243	                    <Archive className="h-3.5 w-3.5" />
244	                  </Button>
245	                </TooltipTrigger>
246	                <TooltipContent>Archive</TooltipContent>
247	              </Tooltip>
248	            </TooltipProvider>
249	            )}
250	          </div>
251	        </TableCell>
252	      </TableRow>
253	
254	      {r.candidate_email && (
255	        <EmailOutreachDialog
256	          open={emailDialogOpen}
257	          onOpenChange={setEmailDialogOpen}
258	          candidateName={r.candidate_name || r.filename}
259	          candidateEmail={r.candidate_email}
260	          jobTitle={jobTitle || "Open Position"}
261	          matchScore={Math.round(r.overall_score ?? 0)}
262	          resumeId={r.resume_id}
263	          jobId={jobId || ""}
264	        />
265	      )}
266	    </>
267	  );
268	};
269	
270	export default React.memo(CandidateRow);
