67	function ScoreRingMini({ score }: { score: number }) {
68	  const size = 56;
69	  const sw = 5;
70	  const r = (size - sw) / 2;
71	  const c = 2 * Math.PI * r;
72	  const v = Math.min(Math.max(score, 0), 100);
73	  const dash = (v / 100) * c;
74	  const color = v >= 70 ? "#22c55e" : v >= 40 ? "#f59e0b" : "#ef4444";
75	  return (
76	    <div
77	      className="relative inline-flex items-center justify-center shrink-0"
78	      style={{ width: size, height: size }}
79	    >
80	      <svg width={size} height={size} className="-rotate-90">
81	        <circle
82	          cx={size / 2}
83	          cy={size / 2}
84	          r={r}
85	          fill="none"
86	          stroke="currentColor"
87	          strokeWidth={sw}
88	          className="text-muted/30"
89	        />
90	        <circle
91	          cx={size / 2}
92	          cy={size / 2}
93	          r={r}
94	          fill="none"
95	          stroke={color}
96	          strokeWidth={sw}
97	          strokeDasharray={`${dash} ${c - dash}`}
98	          strokeLinecap="round"
99	        />
100	      </svg>
101	      <span
102	        className="absolute text-sm font-bold tabular-nums"
103	        style={{ color }}
104	      >
105	        {Math.round(v)}
106	      </span>
107	    </div>
108	  );
109	}
