import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

// ─── Types ────────────────────────────────────────────────────────────────────

export type HireOutcome =
  | "great_hire"
  | "good_hire"
  | "average_hire"
  | "bad_hire"
  | "rejected_interview"
  | "rejected_screening"
  | "no_show"
  | "withdrew";

export interface HireOutcomeRecord {
  id: string;
  user_id: string;
  resume_id: string;
  job_id: string;
  outcome: HireOutcome;
  notes: string | null;
  rank_at_outcome: number | null;
  created_at: string;
}

export interface HitRateStats {
  total_marked: number;
  great_hires: number;
  good_hires: number;
  bad_hires: number;
  hit_rate_percent: number;
  avg_score_of_great: number;
  avg_score_of_bad: number;
}

interface UpsertOutcomeParams {
  resumeId: string;
  jobId: string;
  outcome: HireOutcome;
  notes?: string;
  currentScore?: number;
}

// ─── Hook: useHireOutcome ────────────────────────────────────────────────────

/**
 * Gets the current outcome for a specific resume+job combination.
 */
export function useHireOutcome(resumeId: string | undefined, jobId: string | undefined) {
  return useQuery<HireOutcomeRecord | null>({
    queryKey: ["hire-outcome", resumeId, jobId],
    queryFn: async (): Promise<HireOutcomeRecord | null> => {
      if (!resumeId || !jobId) return null;

      const { data, error } = await (supabase as any)
        .from("hire_outcomes")
        .select("*")
        .eq("resume_id", resumeId)
        .eq("job_id", jobId)
        .maybeSingle();

      if (error) throw error;
      return data as HireOutcomeRecord | null;
    },
    enabled: !!resumeId && !!jobId,
    staleTime: 2 * 60 * 1000, // 2 minutes
  });
}

// ─── Hook: useSetHireOutcome ─────────────────────────────────────────────────

/**
 * Upserts a hire outcome for a resume+job combination.
 */
export function useSetHireOutcome() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation<HireOutcomeRecord, Error, UpsertOutcomeParams>({
    mutationFn: async ({ resumeId, jobId, outcome, notes, currentScore }: UpsertOutcomeParams): Promise<HireOutcomeRecord> => {
      if (!user?.id) throw new Error("Not authenticated");

      const payload = {
        user_id: user.id,
        resume_id: resumeId,
        job_id: jobId,
        outcome,
        notes: notes ?? null,
        rank_at_outcome: currentScore != null ? Math.round(currentScore) : null,
      };

      const { data, error } = await (supabase as any)
        .from("hire_outcomes")
        .upsert(payload, { onConflict: "resume_id,job_id" })
        .select()
        .single();

      if (error) throw error;
      return data as HireOutcomeRecord;
    },

    onSuccess: (data) => {
      toast.success("Outcome saved");
      queryClient.invalidateQueries({ queryKey: ["hire-outcome", data.resume_id, data.job_id] });
      queryClient.invalidateQueries({ queryKey: ["hit-rate"] });
    },

    onError: (error) => {
      toast.error(`Failed to save outcome: ${error.message}`);
    },
  });
}

// ─── Hook: useDeleteHireOutcome ──────────────────────────────────────────────

/**
 * Removes a hire outcome record.
 */
export function useDeleteHireOutcome() {
  const queryClient = useQueryClient();

  return useMutation<void, Error, { resumeId: string; jobId: string }>({
    mutationFn: async ({ resumeId, jobId }) => {
      const { error } = await (supabase as any)
        .from("hire_outcomes")
        .delete()
        .eq("resume_id", resumeId)
        .eq("job_id", jobId);

      if (error) throw error;
    },

    onSuccess: (_data, { resumeId, jobId }) => {
      toast.success("Outcome removed");
      queryClient.invalidateQueries({ queryKey: ["hire-outcome", resumeId, jobId] });
      queryClient.invalidateQueries({ queryKey: ["hit-rate"] });
    },

    onError: (error) => {
      toast.error(`Failed to remove outcome: ${error.message}`);
    },
  });
}

// ─── Hook: useHitRate ───────────────────────────────────────────────────────

/**
 * Fetches the user's aggregate hit rate statistics.
 */
export function useHitRate() {
  const { user } = useAuth();

  return useQuery<HitRateStats | null>({
    queryKey: ["hit-rate", user?.id],
    queryFn: async (): Promise<HitRateStats | null> => {
      if (!user?.id) return null;

      const { data, error } = await (supabase as any).rpc("user_hit_rate", {
        p_user_id: user.id,
      });

      if (error) throw error;

      // RPC returns an array with one row
      const row = Array.isArray(data) ? data[0] : data;
      if (!row) return null;
      return row as HitRateStats;
    },
    enabled: !!user?.id,
    staleTime: 5 * 60 * 1000, // 5 minutes
  });
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface DuplicateMatch {
  duplicate_resume_id: string;
  duplicate_job_id: string;
  duplicate_job_title: string;
  match_type: "email" | "phone" | "embedding";
  similarity: number;
}

interface FindDuplicatesResponse {
  duplicates: DuplicateMatch[];
}

// ─── Hook: useDuplicates ────────────────────────────────────────────────────

/**
 * Finds duplicate resumes across jobs for a given resume.
 * Uses the find-duplicates edge function which calls the find_resume_duplicates RPC.
 * 10 min staleTime — duplicates don't change frequently.
 */
export function useDuplicates(resumeId: string | undefined) {
  return useQuery<DuplicateMatch[]>({
    queryKey: ["duplicates", resumeId],
    queryFn: async (): Promise<DuplicateMatch[]> => {
      if (!resumeId) return [];

      const { data, error } = await supabase.functions.invoke<FindDuplicatesResponse>(
        "find-duplicates",
        { body: { resume_id: resumeId } },
      );

      if (error) throw error;
      return data?.duplicates ?? [];
    },
    enabled: !!resumeId,
    staleTime: 10 * 60 * 1000, // 10 minutes
    retry: 1,
  });
}

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    // ── Auth ──────────────────────────────────────────────────────────────────
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    const token = authHeader.replace("Bearer ", "");
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(token);

    if (authError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ── Validate input ────────────────────────────────────────────────────────
    const body = await req.json() as { resume_id?: string };
    const { resume_id } = body;

    if (!resume_id || typeof resume_id !== "string") {
      return new Response(JSON.stringify({ error: "resume_id is required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ── Verify resume belongs to this user ────────────────────────────────────
    const { data: resume, error: resumeError } = await supabase
      .from("resumes")
      .select("id, job_id, jobs!inner(user_id)")
      .eq("id", resume_id)
      .single();

    if (resumeError || !resume) {
      return new Response(JSON.stringify({ error: "Resume not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Type assertion for the joined data
    const jobData = resume.jobs as unknown as { user_id: string };
    if (jobData.user_id !== user.id) {
      return new Response(JSON.stringify({ error: "Forbidden" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ── Call RPC ──────────────────────────────────────────────────────────────
    const { data: duplicates, error: rpcError } = await supabase.rpc(
      "find_resume_duplicates",
      { p_resume_id: resume_id },
    );

    if (rpcError) {
      console.error("find_resume_duplicates RPC error:", rpcError);
      throw new Error("Duplicate search failed");
    }

    return new Response(
      JSON.stringify({ duplicates: duplicates ?? [] }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown error";
    console.error("find-duplicates error:", message);
    return new Response(JSON.stringify({ error: message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Badge } from "@/components/ui/badge";
import { ChevronDown, RotateCcw, Star, ThumbsUp, Minus, ThumbsDown } from "lucide-react";
import { cn } from "@/lib/utils";
import type { HireOutcome } from "@/hooks/useHireOutcomes";
import { useHireOutcome, useSetHireOutcome, useDeleteHireOutcome } from "@/hooks/useHireOutcomes";

// ─── Types ────────────────────────────────────────────────────────────────────

interface HireOutcomeCardProps {
  resumeId: string;
  jobId: string;
  currentScore?: number;
}

// ─── Constants ───────────────────────────────────────────────────────────────

const PRIMARY_OUTCOMES: Array<{
  value: HireOutcome;
  label: string;
  icon: React.ReactNode;
  colorClass: string;
  badgeClass: string;
}> = [
  {
    value: "great_hire",
    label: "Great hire",
    icon: <Star className="h-4 w-4" />,
    colorClass: "border-emerald-200 bg-emerald-50 text-emerald-700 hover:bg-emerald-100 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400 dark:hover:bg-emerald-900/30",
    badgeClass: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
  },
  {
    value: "good_hire",
    label: "Good hire",
    icon: <ThumbsUp className="h-4 w-4" />,
    colorClass: "border-blue-200 bg-blue-50 text-blue-700 hover:bg-blue-100 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400 dark:hover:bg-blue-900/30",
    badgeClass: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
  },
  {
    value: "average_hire",
    label: "Average",
    icon: <Minus className="h-4 w-4" />,
    colorClass: "border-amber-200 bg-amber-50 text-amber-700 hover:bg-amber-100 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400 dark:hover:bg-amber-900/30",
    badgeClass: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
  },
  {
    value: "bad_hire",
    label: "Bad hire",
    icon: <ThumbsDown className="h-4 w-4" />,
    colorClass: "border-red-200 bg-red-50 text-red-700 hover:bg-red-100 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400 dark:hover:bg-red-900/30",
    badgeClass: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
  },
];

const DROPDOWN_OUTCOMES: Array<{ value: HireOutcome; label: string }> = [
  { value: "rejected_interview", label: "Rejected at interview" },
  { value: "rejected_screening", label: "Rejected at screening" },
  { value: "no_show", label: "No show" },
  { value: "withdrew", label: "Withdrew" },
];

const ALL_OUTCOMES = [...PRIMARY_OUTCOMES.map((o) => ({ value: o.value, label: o.label })), ...DROPDOWN_OUTCOMES];

function getOutcomeDisplay(outcome: HireOutcome) {
  const primary = PRIMARY_OUTCOMES.find((o) => o.value === outcome);
  if (primary) return primary;
  const dropdown = DROPDOWN_OUTCOMES.find((o) => o.value === outcome);
  return dropdown
    ? {
        value: dropdown.value,
        label: dropdown.label,
        icon: <Minus className="h-4 w-4" />,
        colorClass: "border-border bg-muted/50 text-muted-foreground",
        badgeClass: "border-border bg-muted/50 text-muted-foreground",
      }
    : null;
}

// ─── Component ───────────────────────────────────────────────────────────────

export default function HireOutcomeCard({ resumeId, jobId, currentScore }: HireOutcomeCardProps) {
  const { data: existingOutcome, isLoading } = useHireOutcome(resumeId, jobId);
  const { mutate: setOutcome, isPending: isSaving } = useSetHireOutcome();
  const { mutate: deleteOutcome, isPending: isDeleting } = useDeleteHireOutcome();

  const [selected, setSelected] = useState<HireOutcome | null>(null);
  const [notes, setNotes] = useState("");
  const [isEditing, setIsEditing] = useState(false);

  // Determine current state
  const currentOutcome = existingOutcome?.outcome ?? null;
  const currentNotes = existingOutcome?.notes ?? "";
  const display = getOutcomeDisplay(currentOutcome ?? (selected as HireOutcome));

  // When editing, use local state; when not, show saved state
  const showForm = isEditing || (!currentOutcome && selected !== null);

  function handleSelectOutcome(outcome: HireOutcome) {
    setSelected(outcome);
    if (!isEditing && currentOutcome) {
      setIsEditing(true);
      setNotes(currentNotes);
    }
  }

  function handleStartEdit() {
    setSelected(currentOutcome);
    setNotes(currentNotes);
    setIsEditing(true);
  }

  function handleCancel() {
    setSelected(null);
    setNotes("");
    setIsEditing(false);
  }

  function handleSave() {
    const outcomeToSave = isEditing ? (selected ?? currentOutcome) : selected;
    if (!outcomeToSave) return;

    setOutcome(
      { resumeId, jobId, outcome: outcomeToSave, notes: notes.trim() || undefined, currentScore },
      {
        onSuccess: () => {
          setSelected(null);
          setNotes("");
          setIsEditing(false);
        },
      },
    );
  }

  function handleDelete() {
    deleteOutcome(
      { resumeId, jobId },
      {
        onSuccess: () => {
          setSelected(null);
          setNotes("");
          setIsEditing(false);
        },
      },
    );
  }

  if (isLoading) {
    return (
      <div className="rounded-lg border border-border p-4 animate-pulse">
        <div className="h-4 bg-muted rounded w-32 mb-3" />
        <div className="flex gap-2">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="h-9 bg-muted rounded flex-1" />
          ))}
        </div>
      </div>
    );
  }

  // Saved state (not editing)
  if (currentOutcome && !isEditing) {
    const savedDisplay = getOutcomeDisplay(currentOutcome);
    const outcomeLabel = ALL_OUTCOMES.find((o) => o.value === currentOutcome)?.label ?? currentOutcome;

    return (
      <div className="rounded-lg border border-border p-4 space-y-3">
        <div className="flex items-center justify-between">
          <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider">
            Hire Outcome
          </p>
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="sm"
              className="h-7 text-xs text-muted-foreground"
              onClick={handleStartEdit}
            >
              Change
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7 text-muted-foreground hover:text-destructive"
              onClick={handleDelete}
              disabled={isDeleting}
            >
              <RotateCcw className="h-3 w-3" />
            </Button>
          </div>
        </div>

        <Badge
          variant="outline"
          className={cn(
            "text-sm px-3 py-1 h-auto font-medium capitalize gap-1.5 inline-flex items-center",
            savedDisplay?.badgeClass,
          )}
        >
          {savedDisplay?.icon}
          {outcomeLabel}
        </Badge>

        {currentNotes && (
          <p className="text-xs text-muted-foreground leading-relaxed border-l-2 border-border pl-3">
            {currentNotes}
          </p>
        )}
      </div>
    );
  }

  // Input state (new or editing)
  return (
    <div className="rounded-lg border border-border p-4 space-y-3">
      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider">
        {isEditing ? "Change Outcome" : "Mark Hire Outcome"}
      </p>

      {/* Primary outcome buttons */}
      <div className="grid grid-cols-2 gap-2">
        {PRIMARY_OUTCOMES.map((o) => {
          const active = (isEditing ? selected : selected) === o.value;
          return (
            <Button
              key={o.value}
              variant="outline"
              size="sm"
              className={cn(
                "h-9 justify-start gap-1.5 text-xs font-medium transition-all border",
                active ? o.colorClass : "text-muted-foreground hover:text-foreground",
                active && "ring-1 ring-offset-1",
              )}
              onClick={() => handleSelectOutcome(o.value)}
            >
              {o.icon}
              {o.label}
            </Button>
          );
        })}
      </div>

      {/* Dropdown for additional outcomes */}
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            variant="ghost"
            size="sm"
            className={cn(
              "h-8 text-xs text-muted-foreground gap-1 w-full justify-start",
              DROPDOWN_OUTCOMES.some((o) => o.value === selected) && "text-foreground",
            )}
          >
            <ChevronDown className="h-3 w-3" />
            {DROPDOWN_OUTCOMES.some((o) => o.value === selected)
              ? DROPDOWN_OUTCOMES.find((o) => o.value === selected)?.label
              : "More outcomes (rejected, withdrew, no show...)"}
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start" className="w-56">
          {DROPDOWN_OUTCOMES.map((o) => (
            <DropdownMenuItem
              key={o.value}
              onClick={() => handleSelectOutcome(o.value)}
              className={selected === o.value ? "bg-muted" : ""}
            >
              {o.label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>

      {/* Notes textarea — show when outcome is selected */}
      {selected && (
        <div className="space-y-2 animate-in fade-in slide-in-from-top-1 duration-150">
          <Textarea
            placeholder="Optional notes (what went well, what didn't...)"
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            className="min-h-[80px] text-sm resize-none"
          />
          <div className="flex items-center justify-end gap-2">
            {isEditing && (
              <Button
                variant="ghost"
                size="sm"
                className="h-8 text-xs"
                onClick={handleCancel}
              >
                Cancel
              </Button>
            )}
            <Button
              size="sm"
              className="h-8 text-xs"
              onClick={handleSave}
              disabled={isSaving || !selected}
            >
              {isSaving ? "Saving..." : "Save outcome"}
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Target, TrendingUp, TrendingDown, Minus } from "lucide-react";
import { useHitRate } from "@/hooks/useHireOutcomes";
import { cn } from "@/lib/utils";

// ─── Component ───────────────────────────────────────────────────────────────

export default function HitRateWidget() {
  const { data: stats, isLoading, error } = useHitRate();

  if (isLoading) {
    return (
      <Card className="animate-pulse">
        <CardHeader className="pb-3">
          <div className="h-4 bg-muted rounded w-40" />
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="h-10 bg-muted rounded w-24" />
          <div className="h-3 bg-muted rounded w-56" />
          <div className="h-3 bg-muted rounded w-48" />
        </CardContent>
      </Card>
    );
  }

  if (error || !stats) return null;
  if (stats.total_marked === 0) return null;

  const delta = stats.avg_score_of_great - stats.avg_score_of_bad;
  const hasScoreData = stats.avg_score_of_great > 0 || stats.avg_score_of_bad > 0;

  const hitRateColor =
    stats.hit_rate_percent >= 70
      ? "text-emerald-600 dark:text-emerald-400"
      : stats.hit_rate_percent >= 40
      ? "text-amber-600 dark:text-amber-400"
      : "text-red-600 dark:text-red-400";

  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-sm font-medium flex items-center gap-2">
          <Target className="h-4 w-4 text-muted-foreground" />
          Hiring Quality
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Big hit rate number */}
        <div className="flex items-end gap-3">
          <span className={cn("text-4xl font-bold tabular-nums leading-none", hitRateColor)}>
            {stats.hit_rate_percent}%
          </span>
          <div className="pb-0.5">
            <p className="text-xs text-muted-foreground leading-tight">hit rate</p>
            <p className="text-xs text-muted-foreground leading-tight">
              {stats.total_marked} outcome{stats.total_marked !== 1 ? "s" : ""} marked
            </p>
          </div>
        </div>

        {/* Breakdown badges */}
        <div className="flex flex-wrap gap-1.5">
          {stats.great_hires > 0 && (
            <Badge variant="outline" className="text-xs border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400">
              {stats.great_hires} great
            </Badge>
          )}
          {stats.good_hires > 0 && (
            <Badge variant="outline" className="text-xs border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400">
              {stats.good_hires} good
            </Badge>
          )}
          {stats.bad_hires > 0 && (
            <Badge variant="outline" className="text-xs border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400">
              {stats.bad_hires} poor
            </Badge>
          )}
        </div>

        {/* Score insights */}
        {hasScoreData && (
          <div className="rounded-lg bg-muted/50 p-3 space-y-1.5 text-xs">
            {stats.avg_score_of_great > 0 && (
              <div className="flex items-center gap-1.5 text-muted-foreground">
                <TrendingUp className="h-3 w-3 text-emerald-500 shrink-0" />
                <span>Great hires averaged <span className="font-semibold text-foreground">{stats.avg_score_of_great}%</span> match score</span>
              </div>
            )}
            {stats.avg_score_of_bad > 0 && (
              <div className="flex items-center gap-1.5 text-muted-foreground">
                <TrendingDown className="h-3 w-3 text-red-500 shrink-0" />
                <span>Poor hires averaged <span className="font-semibold text-foreground">{stats.avg_score_of_bad}%</span> match score</span>
              </div>
            )}
            {hasScoreData && stats.avg_score_of_great > 0 && stats.avg_score_of_bad > 0 && (
              <div className="flex items-center gap-1.5 pt-1 border-t border-border/50">
                {delta > 0 ? (
                  <>
                    <TrendingUp className="h-3 w-3 text-primary shrink-0" />
                    <span className="text-foreground font-medium">
                      Your bad hires score {delta}pt{delta !== 1 ? "s" : ""} below great hires — AI is learning
                    </span>
                  </>
                ) : delta < 0 ? (
                  <>
                    <Minus className="h-3 w-3 text-muted-foreground shrink-0" />
                    <span className="text-muted-foreground">
                      Score correlation not yet clear — keep marking outcomes
                    </span>
                  </>
                ) : (
                  <>
                    <Minus className="h-3 w-3 text-muted-foreground shrink-0" />
                    <span className="text-muted-foreground">No score delta yet</span>
                  </>
                )}
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Mail, Phone, Layers } from "lucide-react";
import type { DuplicateMatch } from "@/hooks/useDuplicates";

// ─── Types ────────────────────────────────────────────────────────────────────

interface DuplicateDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  candidateName: string;
  duplicates: DuplicateMatch[];
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function MatchTypeIcon({ type }: { type: DuplicateMatch["match_type"] }) {
  if (type === "email") return <Mail className="h-3.5 w-3.5 text-blue-500" />;
  if (type === "phone") return <Phone className="h-3.5 w-3.5 text-emerald-500" />;
  return <Layers className="h-3.5 w-3.5 text-purple-500" />;
}

function MatchTypeBadge({ type, similarity }: { type: DuplicateMatch["match_type"]; similarity: number }) {
  if (type === "email") {
    return (
      <Badge variant="outline" className="text-xs gap-1 border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400">
        <Mail className="h-3 w-3" />
        Email match
      </Badge>
    );
  }
  if (type === "phone") {
    return (
      <Badge variant="outline" className="text-xs gap-1 border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400">
        <Phone className="h-3 w-3" />
        Phone match
      </Badge>
    );
  }
  return (
    <Badge variant="outline" className="text-xs gap-1 border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400">
      <Layers className="h-3 w-3" />
      {Math.round(similarity * 100)}% similar
    </Badge>
  );
}

// ─── Component ───────────────────────────────────────────────────────────────

export default function DuplicateDialog({
  open,
  onOpenChange,
  candidateName,
  duplicates,
}: DuplicateDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="text-base flex items-center gap-2">
            <Layers className="h-4 w-4 text-orange-500" />
            Duplicate Matches — {candidateName}
          </DialogTitle>
        </DialogHeader>

        <p className="text-sm text-muted-foreground -mt-1">
          This candidate appears in {duplicates.length} other job{duplicates.length !== 1 ? "s" : ""}.
        </p>

        <ScrollArea className="max-h-[360px] pr-1">
          <div className="space-y-2">
            {duplicates.map((dup) => (
              <div
                key={`${dup.duplicate_resume_id}-${dup.duplicate_job_id}`}
                className="rounded-lg border border-border p-3 space-y-2"
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0">
                    <p className="text-sm font-medium text-foreground truncate">
                      {dup.duplicate_job_title}
                    </p>
                  </div>
                  <MatchTypeBadge type={dup.match_type} similarity={dup.similarity} />
                </div>
              </div>
            ))}
          </div>
        </ScrollArea>

        {duplicates.length === 0 && (
          <div className="flex flex-col items-center justify-center py-8 text-muted-foreground">
            <Layers className="h-8 w-8 mb-2 opacity-30" />
            <p className="text-sm">No duplicates found</p>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { Layers } from "lucide-react";
import { useDuplicates } from "@/hooks/useDuplicates";
import DuplicateDialog from "@/components/candidate/DuplicateDialog";

// ─── Types ────────────────────────────────────────────────────────────────────

interface DuplicateBadgeProps {
  resumeId: string;
  candidateName?: string;
}

// ─── Component ───────────────────────────────────────────────────────────────

export default function DuplicateBadge({ resumeId, candidateName = "Candidate" }: DuplicateBadgeProps) {
  const { data: duplicates } = useDuplicates(resumeId);
  const [dialogOpen, setDialogOpen] = useState(false);

  if (!duplicates || duplicates.length === 0) return null;

  // Summarize match types for tooltip
  const hasEmail = duplicates.some((d) => d.match_type === "email");
  const hasPhone = duplicates.some((d) => d.match_type === "phone");
  const hasEmbedding = duplicates.some((d) => d.match_type === "embedding");

  const matchSummary = [
    hasEmail && "email",
    hasPhone && "phone",
    hasEmbedding && "resume similarity",
  ]
    .filter(Boolean)
    .join(", ");

  return (
    <>
      <TooltipProvider delayDuration={300}>
        <Tooltip>
          <TooltipTrigger asChild>
            <Badge
              variant="outline"
              className="text-xs px-1.5 py-0 h-4 gap-0.5 border-orange-300 text-orange-600 bg-orange-50 dark:border-orange-700 dark:bg-orange-900/20 dark:text-orange-400 cursor-pointer hover:bg-orange-100 dark:hover:bg-orange-900/30 transition-colors shrink-0"
              onClick={(e) => {
                e.stopPropagation();
                setDialogOpen(true);
              }}
            >
              <Layers className="h-2.5 w-2.5" />
              {duplicates.length} dup{duplicates.length !== 1 ? "s" : ""}
            </Badge>
          </TooltipTrigger>
          <TooltipContent side="top" className="max-w-[220px]">
            <p className="text-xs font-medium">Duplicate candidate</p>
            <p className="text-xs text-muted-foreground mt-0.5">
              Matched by {matchSummary} in {duplicates.length} other job{duplicates.length !== 1 ? "s" : ""}:
            </p>
            <ul className="mt-1 space-y-0.5">
              {duplicates.slice(0, 3).map((d) => (
                <li key={`${d.duplicate_resume_id}-${d.duplicate_job_id}`} className="text-xs text-muted-foreground truncate">
                  • {d.duplicate_job_title}
                </li>
              ))}
              {duplicates.length > 3 && (
                <li className="text-xs text-muted-foreground">+{duplicates.length - 3} more</li>
              )}
            </ul>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>

      <DuplicateDialog
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        candidateName={candidateName}
        duplicates={duplicates}
      />
    </>
  );
}

